-- SnogMarryAvoid: tag players with a face, a role and a note.
-- Players tagged :( can't be invited, and their invites are declined automatically.

local ADDON_NAME = ...

local MEDIA = "Interface\\AddOns\\SnogMarryAvoid\\Media\\"

-- Icons are generated by tools/make_faces.lua.
local FACES = {
	{ icon = MEDIA .. "happy", label = "Happy" },
	{ icon = MEDIA .. "meh", label = "Meh" },
	{ icon = MEDIA .. "avoid", label = "Avoid" },
	{ icon = MEDIA .. "review", label = "Review" }, -- shared reports only; you can't pick it yourself
}
local FACE_AVOID = 3
local FACE_REVIEW = 4
local NUM_PICKABLE = 3

-- Guilds whose members are avoided by everyone using the addon (on top of your own /sma avoidguild rules).
local BUILTIN_GUILDS = { "Olympus" }

-- A shared :( report from this many different players locks a non-guild player in as avoided.
-- Fewer reports put them under review: not blocked, but you get a warning when you meet them.
local STRIKES = 3

-- An avoided-guild claim from other players locks someone in only when this many different reporter
-- codes make it. Otherwise it waits until you see the player yourself and the game shows their guild.
local GUILD_CORROBORATION = 2

----------------------------------------------------------------------------------------------------
-- Reporter code (anti-alt)
----------------------------------------------------------------------------------------------------
-- Strikes count different reporters, and alts of one person must count once. Each list is sent
-- with a reporter code worked out from the sender's BattleTag at the moment of sending:
--   * It's a number from 0 to REPORTER_CODES-1. Millions of BattleTags share every value, so the
--     code holds far too little information to lead back to a BattleTag, or to confirm a guess.
--   * The BattleTag is only read into a local variable here. It's never saved, sent or printed,
--     and the code itself isn't saved either; it's recalculated each time.
--   * Being derived, not stored, the code can't be changed by editing SavedVariables. All WoW
--     accounts and characters under one Battle.net account get the same code.
-- Two different people sometimes share a code (about 1 in 256 per pair). They then count as one
-- strike, which only ever makes a lock slower, never wrongly faster.
local REPORTER_CODES = 256
local REPORTER_SALT = "SnogMarryAvoid reporter v1:"

local function ReporterCode()
	if not BNGetInfo then return nil end
	local _, battleTag = BNGetInfo()
	if type(battleTag) ~= "string" or not (not canaccessvalue or canaccessvalue(battleTag)) or battleTag == "" then
		return nil
	end
	-- FNV-style hash over the salted, lower-cased BattleTag, using arithmetic only (Lua 5.1).
	-- h * 16777619 can reach 2^56, past exact double precision, so the multiply is split:
	-- 16777619 = 256 * 65536 + 403.
	local s = REPORTER_SALT .. strlower(battleTag)
	local h = 2166136261
	for i = 1, #s do
		h = (h + s:byte(i)) % 4294967296
		h = (h * 403 + ((h * 256) % 65536) * 65536) % 4294967296
	end
	return h % REPORTER_CODES
end

local ROLES = {
	{ key = "TANK", label = "Tank", atlas = "roleicon-tiny-tank" },
	{ key = "HEALER", label = "Healer", atlas = "roleicon-tiny-healer" },
	{ key = "DAMAGER", label = "DPS", atlas = "roleicon-tiny-dps" },
}
local ROLE_BY_KEY = {}
for _, r in ipairs(ROLES) do ROLE_BY_KEY[r.key] = r end

-- Unit popup menus that show a player. TARGET/FOCUS also cover NPCs, which are filtered out below.
local MENU_TYPES = {
	"PLAYER", "PARTY", "RAID_PLAYER", "RAID", "FRIEND", "ENEMY_PLAYER", "TARGET", "FOCUS",
	"CHAT_ROSTER", "GUILD", "COMMUNITIES_GUILD_MEMBER", "COMMUNITIES_WOW_MEMBER",
	"RECENT_ALLY", "PVP_SCOREBOARD",
}

local PREFIX = "|cffff69b4SnogMarryAvoid|r: "

local db -- SnogMarryAvoidDB, set on ADDON_LOADED
local SMA = {}

local function Print(msg)
	print(PREFIX .. msg)
end

-- Inline texture markup for a face, for chat, menus and popups.
local function FaceText(face, size)
	local f = FACES[face]
	size = size or 14
	return f and ("|T" .. f.icon .. ":" .. size .. ":" .. size .. "|t") or ""
end

-- Text from other players is shown escaped so it can't inject links, textures or colours.
local function Escape(s)
	return (s or ""):gsub("|", "||")
end

----------------------------------------------------------------------------------------------------
-- Names
----------------------------------------------------------------------------------------------------
-- WoW Forever uses regional unique names: a player is "First Surname" with no realm, and
-- UnitName() returns ("First Surname", "Surname"). Blizzard sometimes joins the surname with the
-- realm separator instead ("First-Surname"), so both forms are folded into one key.

local seps = Constants and Constants.CharacterNameSeparatorConsts
local SURNAME_SEP = seps and seps.CHARACTERNAME_SURNAME_SEPARATOR or " "
local REALM_SEP = seps and seps.CHARACTERNAME_REALMNAME_SEPARATOR or "-"

local function Accessible(v)
	return v ~= nil and (not canaccessvalue or canaccessvalue(v))
end

local function RegionalNames()
	return RegionalUniqueNamesEnabled and RegionalUniqueNamesEnabled()
end

-- Clean up a name for display and storage.
local function DisplayName(name)
	if type(name) ~= "string" or not Accessible(name) then return nil end
	name = strtrim(name)
	if name == "" then return nil end
	if RegionalNames() and REALM_SEP ~= SURNAME_SEP then
		local i = name:find(REALM_SEP, 1, true)
		if i then
			name = name:sub(1, i - 1) .. SURNAME_SEP .. name:sub(i + #REALM_SEP)
		end
	elseif not RegionalNames() and not name:find(REALM_SEP, 1, true) then
		name = name .. REALM_SEP .. GetNormalizedRealmName()
	end
	return name
end

local function Key(name)
	local display = DisplayName(name)
	return display and strlower(display)
end

local function NameFromUnit(unit)
	if not Accessible(unit) or not UnitExists(unit) then return nil end
	local isPlayer = UnitIsPlayer(unit)
	if not Accessible(isPlayer) or not isPlayer then return nil end
	local name, second = UnitName(unit)
	if not Accessible(name) then return nil end
	if not RegionalNames() and Accessible(second) and second and second ~= "" then
		name = name .. REALM_SEP .. second
	end
	return name
end

local function IsMe(name)
	return Key(name) == Key(NameFromUnit("player"))
end

-- Returns the player's name (and GUID if known) for a unit popup menu, or nil if it isn't a player.
local function NameFromContext(contextData)
	if not contextData then return nil end
	local unit, guid = contextData.unit, nil
	local name
	if unit then
		name = NameFromUnit(unit)
		if name then
			local g = UnitGUID(unit)
			if Accessible(g) then guid = g end
		end
	elseif Accessible(contextData.name) and contextData.name then
		name = contextData.name
		local surname = contextData.surname or contextData.server
		if Accessible(surname) and surname and surname ~= "" then
			name = name .. REALM_SEP .. surname
		end
	end
	if not name or IsMe(name) then return nil end
	return name, guid
end

----------------------------------------------------------------------------------------------------
-- Data
----------------------------------------------------------------------------------------------------

function SMA:Get(name)
	local key = Key(name)
	return key and db.players[key], key
end

function SMA:GetByGUID(guid)
	if not Accessible(guid) or not guid then return nil end
	for _, entry in pairs(db.players) do
		if entry.guid == guid then return entry end
	end
end

-- Returns the rule that matches a guild name (built-in or your own), or nil.
local function MatchGuildRule(guildName)
	if type(guildName) ~= "string" or guildName == "" then return nil end
	local lower = strlower(guildName)
	for _, prefix in ipairs(BUILTIN_GUILDS) do
		if lower:sub(1, #prefix) == strlower(prefix) then return prefix end
	end
	for _, prefix in ipairs(db.avoidGuilds) do
		if lower:sub(1, #prefix) == strlower(prefix) then return prefix end
	end
end

-- Avoid entries received from other players, kept per sender in db.inbox[senderKey] =
-- { from, via = "guild"|"direct", updated, entries = { [playerKey] = { name, role, guild } } }. No notes.
-- They never override your own entries, and ones you delete (db.dismissed) stay hidden.
--
-- A received player's status:
--   "guild"   in an auto-avoided guild (Olympus or your own rule): avoided
--   "strikes" reported by STRIKES or more different players: avoided
--   "review"  reported by fewer: not blocked, but you're warned when you meet them
-- Guild and strikes players are locked into db.locked[key] = { name, role, guild, reason, at }, so they
-- stay avoided even if the reporters later take them off their lists.
--
-- A sender's "they're in Olympus" claim is never trusted on its own (a modified addon could claim it
-- for anyone). It counts only when GUILD_CORROBORATION different reporter codes make it, and only
-- until you see the player yourself: then their real guild decides (see SMA:CheckUnitGuild).
-- db.guildSeen[key] = guildName records players you've seen who are NOT in an avoided guild.
--
-- Returns info = { name, role, status, face, from, count, strikes, guild, claim }, key; or nil, key.
function SMA:GetShared(name)
	local key = Key(name)
	if not key or db.dismissed[key] then return nil, key end
	local found, from, count = nil, nil, 0
	local codes, strikes = {}, 0
	local claimCodes, claims, claimGuild = {}, 0, nil
	for _, box in pairs(db.inbox) do
		local e = box.entries[key]
		if e then
			count = count + 1
			if not found then found, from = e, box.from end
			-- a strike per reporter code: alts of one person count once, lists without a code never count
			if box.code and not codes[box.code] then
				codes[box.code] = true
				strikes = strikes + 1
			end
			if MatchGuildRule(e.guild) then
				claimGuild = claimGuild or e.guild
				if box.code and not claimCodes[box.code] then
					claimCodes[box.code] = true
					claims = claims + 1
				end
			end
		end
	end
	local locked = db.locked[key]
	if not found and not locked then return nil, key end
	if db.guildSeen[key] then claimGuild, claims = nil, 0 end -- you've seen them yourself: not in it
	local guild
	if claims >= GUILD_CORROBORATION then
		guild = claimGuild
	elseif locked and locked.reason == "guild" then
		guild = locked.guild
	end
	local status
	if guild then
		status = "guild"
	elseif locked or strikes >= STRIKES then
		status = "strikes"
	else
		status = "review"
	end
	local src = found or locked
	return {
		name = src.name,
		role = src.role,
		status = status,
		face = status == "review" and FACE_REVIEW or FACE_AVOID,
		from = from,
		count = count,     -- characters that reported them
		strikes = strikes, -- different reporter codes among them
		guild = guild,     -- avoided guild, confirmed by corroboration or a lock
		claim = not guild and claimGuild or nil, -- an unconfirmed avoided-guild claim
	}, key
end

-- Lock in received players who are in an avoided guild or have enough strikes.
function SMA:ApplyLocks(quiet)
	local seen = {}
	for _, box in pairs(db.inbox) do
		for key in pairs(box.entries) do
			if not seen[key] and not db.locked[key] and not db.dismissed[key] then
				seen[key] = true
				local info = self:GetShared(key)
				if info and info.status ~= "review" then
					db.locked[key] = { name = info.name, role = info.role, guild = info.guild, reason = info.status, at = time() }
					if not quiet and not db.players[key] then
						if info.status == "guild" then
							Print(FaceText(FACE_AVOID) .. " " .. Escape(info.name) .. " (guild <" .. Escape(info.guild) .. ">) is now avoided.")
						else
							Print(FaceText(FACE_AVOID) .. " " .. Escape(info.name) .. " was reported by " .. info.strikes .. " different players and is now avoided.")
						end
					end
				end
			end
		end
	end
end

-- Your own entry decides if you have one; otherwise a shared entry counts unless it's under review.
function SMA:IsAvoided(name, guid)
	local entry = self:Get(name) or self:GetByGUID(guid)
	if entry then return entry.face == FACE_AVOID, entry end
	local info = name and self:GetShared(name)
	return info ~= nil and info.status ~= "review", info
end

-- A shared report under review (fewer than STRIKES reporters, not in an avoided guild), and no own entry.
function SMA:GetReview(name, guid)
	if self:Get(name) or self:GetByGUID(guid) then return nil end
	local info = name and self:GetShared(name)
	return info and info.status == "review" and info or nil
end

-- Battle.net friends are never blocked. Matched by GUID when we have one, else by character name
-- (only online friends expose their character, so an offline friend can't be matched by name).
function SMA:IsBNetFriend(name, guid)
	if Accessible(guid) and guid and C_BattleNet and C_BattleNet.GetGameAccountInfoByGUID then
		if C_BattleNet.GetGameAccountInfoByGUID(guid) then return true end
	end
	local key = name and Key(name)
	if not key or not BNGetNumFriends then return false end
	local numFriends = BNGetNumFriends()
	for i = 1, numFriends or 0 do
		for j = 1, C_BattleNet.GetFriendNumGameAccounts(i) or 0 do
			local info = C_BattleNet.GetFriendGameAccountInfo(i, j)
			local charName = info and info.characterName
			if Accessible(charName) and charName and charName ~= "" then
				if Key(charName) == key then return true end
				local realm = info.realmName
				if Accessible(realm) and realm and realm ~= "" and Key(charName .. REALM_SEP .. realm) == key then
					return true
				end
			end
		end
	end
	return false
end

----------------------------------------------------------------------------------------------------
-- Window
----------------------------------------------------------------------------------------------------

local frame

local function MakeLabel(parent, text, y)
	local fs = parent:CreateFontString(nil, "OVERLAY", "GameFontNormal")
	fs:SetPoint("TOPLEFT", 16, y)
	fs:SetText(text)
	return fs
end

local function MakeButton(parent, text, width)
	local b = CreateFrame("Button", nil, parent, "UIPanelButtonTemplate")
	b:SetSize(width, 22)
	b:SetText(text)
	return b
end

local function UpdateToggleButtons(buttons, selected)
	for value, b in pairs(buttons) do
		if value == selected then b:LockHighlight() else b:UnlockHighlight() end
	end
end

function SMA:UpdateBNetWarning()
	local f = frame
	local show = f.face == FACE_AVOID and self:IsBNetFriend(f.nameBox:GetText(), f.guid)
	f.bnetWarning:SetShown(show)
end

function SMA:SetFace(face)
	frame.face = face
	for i, b in ipairs(frame.faceButtons) do
		local selected = i == face
		b.icon:SetDesaturated(not selected)
		b.icon:SetAlpha(selected and 1 or 0.4)
		b.selected:SetShown(selected)
	end
	self:UpdateBNetWarning()
end

-- Highlight the row being edited.
local function UpdateRowSelected(row)
	if row.entry then
		local key = row.entry.key
		row.editingBg:SetShown(key ~= nil and (key == frame.editKey or key == frame.sharedKey))
	end
end

function SMA:SetRole(role)
	frame.role = role
	UpdateToggleButtons(frame.roleButtons, role or "NONE")
end

-- Fill the editor with a player (existing entry or a new one).
function SMA:Load(name, guid)
	local f = self:GetFrame()
	local entry, key, shared = nil, nil, nil
	if name then entry, key = self:Get(name) end
	if name and not entry then shared = self:GetShared(name) end
	f.editKey = entry and key or nil
	f.sharedKey = shared and key or nil
	f.guid = guid or (entry and entry.guid) or nil
	local source = entry or shared
	f.nameBox:SetText(source and source.name or DisplayName(name) or "")
	f.noteBox:SetText(entry and entry.note or "")
	self:SetFace(entry and entry.face or (shared and shared.face) or 1)
	self:SetRole(source and source.role or nil)
	f.deleteButton:SetEnabled(source ~= nil)
	f.saveButton:SetText(entry and (SAVE or "Save") or "Add")
	f.scrollBox:ForEachFrame(UpdateRowSelected)
	if shared then
		local text
		if shared.status == "guild" then
			text = "Guild <" .. Escape(shared.guild) .. ">: always avoided."
		elseif shared.status == "strikes" then
			text = "Reported by " .. STRIKES .. "+ players: avoided."
		else
			text = "Under review: " .. shared.strikes .. " of " .. STRIKES .. " strikes."
			if shared.claim then
				text = text .. " Said to be in <" .. Escape(shared.claim) .. ">, unconfirmed until you see them."
			end
			text = text .. " Pick a face and Save to decide yourself."
		end
		f.sourceText:SetText(text)
	else
		f.sourceText:SetText("")
	end
	f.nameBox:ClearFocus()
	f.noteBox:ClearFocus()
end

function SMA:Save()
	local f = frame
	local name = DisplayName(f.nameBox:GetText())
	if not name then
		Print("Enter a player name first.")
		return
	end
	if not f.face or f.face > NUM_PICKABLE then
		Print("Pick a face first.")
		return
	end
	local key = Key(name)
	local old = f.editKey and db.players[f.editKey]
	if f.editKey and f.editKey ~= key then
		db.players[f.editKey] = nil
	end
	db.dismissed[key] = nil
	db.players[key] = {
		name = name,
		face = f.face or 1,
		role = f.role,
		note = strtrim(f.noteBox:GetText() or ""),
		guid = f.guid or (old and old.guid) or nil,
		auto = old and old.auto or nil,
		updated = time(),
	}
	self:Load(name)
	self:Refresh()
	self:OnOwnListChanged()
end

-- Tag a player from the right-click menu without opening the window. Keeps an existing role and
-- note. A new entry from a group member takes the role they queued as, if any.
function SMA:QuickTag(name, guid, unit, face)
	local display = DisplayName(name)
	local key = display and Key(display)
	if not key then return end
	local old = db.players[key]
	local role = old and old.role
	if not old and unit and UnitGroupRolesAssigned then
		local r = UnitGroupRolesAssigned(unit)
		if Accessible(r) and ROLE_BY_KEY[r] then role = r end
	end
	db.dismissed[key] = nil
	db.players[key] = {
		name = old and old.name or display,
		face = face,
		role = role,
		note = old and old.note or "",
		guid = (Accessible(guid) and guid) or (old and old.guid) or nil,
		auto = old and old.auto or nil,
		updated = time(),
	}
	Print(FaceText(face) .. " " .. Escape(display) .. (old and " updated." or " added."))
	if frame and frame:IsShown() then
		if frame.editKey == key then self:Load(display) end
		self:Refresh()
	end
	self:OnOwnListChanged()
end

-- Remove one of your own entries. An auto-added guild entry you delete isn't added again.
local function RemoveOwn(key)
	local e = db.players[key]
	if e and e.auto then db.autoSkip[key] = true end
	db.players[key] = nil
end

function SMA:Delete()
	if frame.editKey then
		RemoveOwn(frame.editKey)
		self:OnOwnListChanged()
	elseif frame.sharedKey then
		db.dismissed[frame.sharedKey] = true -- stays hidden even when the sender syncs again
		db.locked[frame.sharedKey] = nil
	end
	self:Load(nil)
	self:Refresh()
end

-- Delete several entries by key. Your own entries are removed; received ones are hidden for good.
function SMA:DeleteKeys(keys)
	local ownChanged = false
	for _, key in ipairs(keys) do
		if db.players[key] then
			RemoveOwn(key)
			ownChanged = true
		else
			db.dismissed[key] = true
			db.locked[key] = nil
		end
		if key == frame.editKey or key == frame.sharedKey then self:Load(nil) end
	end
	wipe(frame.checked)
	self:Refresh()
	if ownChanged then self:OnOwnListChanged() end
	Print("Deleted " .. #keys .. " entries.")
end

function SMA:DeleteSelected()
	local keys = {}
	for key in pairs(frame.checked) do keys[#keys + 1] = key end
	if #keys > 0 then self:DeleteKeys(keys) end
end

-- Remove everything: your own entries and all received lists.
function SMA:DeleteAll()
	for key in pairs(db.players) do RemoveOwn(key) end
	wipe(db.inbox)
	wipe(db.dismissed)
	wipe(db.locked)
	wipe(frame.checked)
	self:Load(nil)
	self:Refresh()
	self:OnOwnListChanged()
	Print("Deleted all entries.")
end

function SMA:UpdateSelectionButtons()
	local n = 0
	for _ in pairs(frame.checked) do n = n + 1 end
	frame.deleteSelectedButton:SetText("Delete selected" .. (n > 0 and (" (" .. n .. ")") or ""))
	frame.deleteSelectedButton:SetEnabled(n > 0)
	frame.selectAll:SetChecked(n > 0 and n == frame.listCount)
end

function SMA:Refresh()
	if not frame then return end
	local list = {}
	for key, entry in pairs(db.players) do
		list[#list + 1] = { key = key, name = entry.name, face = entry.face, role = entry.role, note = entry.note }
	end
	local seen = {}
	local function AddShared(key)
		if seen[key] or db.players[key] then return end
		seen[key] = true
		local info = SMA:GetShared(key)
		if not info then return end
		local source
		if info.status == "guild" then
			source = "guild <" .. info.guild .. ">"
		elseif info.status == "strikes" then
			source = STRIKES .. " strikes"
		else
			source = "review " .. info.strikes .. "/" .. STRIKES
			if info.claim then source = source .. ", <" .. info.claim .. ">?" end
		end
		list[#list + 1] = { key = key, name = info.name, face = info.face, role = info.role, from = source }
	end
	for _, box in pairs(db.inbox) do
		for key in pairs(box.entries) do AddShared(key) end
	end
	for key in pairs(db.locked) do AddShared(key) end
	table.sort(list, function(a, b)
		if a.face ~= b.face then return a.face < b.face end
		return strlower(a.name) < strlower(b.name)
	end)
	-- the review group gets its own heading at the bottom
	for i, item in ipairs(list) do
		if item.face == FACE_REVIEW then
			table.insert(list, i, { header = FaceText(FACE_REVIEW) .. " Under review: reported, but not by " .. STRIKES .. " players yet. Proceed with care." })
			break
		end
	end
	-- drop ticks for entries that no longer exist
	local present, count = {}, 0
	for _, item in ipairs(list) do
		if item.key then present[item.key] = true; count = count + 1 end
	end
	for key in pairs(frame.checked) do
		if not present[key] then frame.checked[key] = nil end
	end
	frame.listCount = count
	frame.scrollBox:SetDataProvider(CreateDataProvider(list), ScrollBoxConstants.RetainScrollPosition)
	frame.countText:SetText(count .. " players")
	frame.deleteAllButton:SetEnabled(count > 0)
	self:UpdateSelectionButtons()
end

local function InitRow(row, entry)
	if not row.faceIcon then
		row:SetHighlightTexture("Interface\\QuestFrame\\UI-QuestTitleHighlight", "ADD")
		row.editingBg = row:CreateTexture(nil, "BACKGROUND")
		row.editingBg:SetAllPoints()
		row.editingBg:SetColorTexture(1, 0.82, 0, 0.15)
		row.check = CreateFrame("CheckButton", nil, row, "UICheckButtonTemplate")
		row.check:SetSize(22, 22)
		row.check:SetPoint("LEFT", 0, 0)
		row.check:SetScript("OnClick", function(self)
			frame.checked[row.entry.key] = self:GetChecked() or nil
			SMA:UpdateSelectionButtons()
		end)
		row.faceIcon = row:CreateTexture(nil, "ARTWORK")
		row.faceIcon:SetSize(18, 18)
		row.faceIcon:SetPoint("LEFT", 24, 0)
		row.roleIcon = row:CreateTexture(nil, "ARTWORK")
		row.roleIcon:SetSize(14, 14)
		row.roleIcon:SetPoint("LEFT", 46, 0)
		row.nameText = row:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
		row.nameText:SetPoint("LEFT", 66, 0)
		row.nameText:SetWidth(130)
		row.nameText:SetJustifyH("LEFT")
		row.nameText:SetWordWrap(false)
		row.editButton = CreateFrame("Button", nil, row, "UIPanelButtonTemplate")
		row.editButton:SetSize(44, 20)
		row.editButton:SetPoint("RIGHT", -2, 0)
		row.editButton:SetText("Edit")
		row.editButton:SetScript("OnClick", function()
			SMA:Load(row.entry.name)
			frame.noteBox:SetFocus()
		end)
		row.noteText = row:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		row.noteText:SetPoint("LEFT", 200, 0)
		row.noteText:SetPoint("RIGHT", row.editButton, "LEFT", -4, 0)
		row.noteText:SetJustifyH("LEFT")
		row.noteText:SetWordWrap(false)
		row:SetScript("OnClick", function(self)
			if self.entry.key then SMA:Load(self.entry.name) end
		end)
	end
	row.entry = entry
	local isHeader = entry.header ~= nil
	row.check:SetShown(not isHeader)
	row.editButton:SetShown(not isHeader)
	row.faceIcon:SetShown(not isHeader)
	row.noteText:SetShown(not isHeader)
	row.nameText:ClearAllPoints()
	if isHeader then
		row.roleIcon:Hide()
		row.editingBg:Hide()
		row.nameText:SetPoint("LEFT", 4, 0)
		row.nameText:SetPoint("RIGHT", -4, 0)
		row.nameText:SetFontObject("GameFontNormalSmall")
		row.nameText:SetText(entry.header)
		return
	end
	row.nameText:SetPoint("LEFT", 66, 0)
	row.nameText:SetWidth(130)
	row.nameText:SetFontObject("GameFontHighlight")
	row.check:SetChecked(frame.checked[entry.key] ~= nil)
	row.faceIcon:SetTexture(FACES[entry.face] and FACES[entry.face].icon or nil)
	UpdateRowSelected(row)
	local role = ROLE_BY_KEY[entry.role or ""]
	if role then
		row.roleIcon:SetAtlas(role.atlas)
		row.roleIcon:Show()
	else
		row.roleIcon:Hide()
	end
	if entry.from then
		row.nameText:SetText(Escape(entry.name))
		row.noteText:SetText("|cff888888from " .. Escape(entry.from) .. "|r")
	else
		row.nameText:SetText(entry.name)
		row.noteText:SetText(entry.note or "")
	end
end

