function SMA:Open(name, guid)
	local f = self:GetFrame()
	f:Show()
	self:Load(name, guid)
	self:Refresh()
end

function SMA:Toggle()
	local f = self:GetFrame()
	if f:IsShown() then f:Hide() else self:Open(nil) end
end

----------------------------------------------------------------------------------------------------
-- Right-click menus
----------------------------------------------------------------------------------------------------

local function AddMenuEntries()
	if not (Menu and Menu.ModifyMenu) then return end
	for _, which in ipairs(MENU_TYPES) do
		Menu.ModifyMenu("MENU_UNIT_" .. which, function(_, rootDescription, contextData)
			local name, guid = NameFromContext(contextData)
			if not name then return end
			local unit = contextData and contextData.unit
			local entry = SMA:Get(name)
			local shared = not entry and SMA:GetShared(name)
			local face = entry and entry.face or (shared and shared.face)
			local text = "SnogMarryAvoid"
			if face then text = FaceText(face) .. " " .. text end
			rootDescription:CreateDivider()
			-- Submenu: tag in one click, or open the window for the role and note.
			local sub = rootDescription:CreateButton(text)
			local function IsSelected(f)
				local e = SMA:Get(name)
				return e ~= nil and e.face == f
			end
			local function SetSelected(f)
				SMA:QuickTag(name, guid, unit, f)
				return MenuResponse and MenuResponse.Close
			end
			for i = 1, NUM_PICKABLE do
				local f = FACES[i]
				sub:CreateRadio(FaceText(i) .. " " .. f.label, IsSelected, SetSelected, i)
			end
			sub:CreateDivider()
			sub:CreateButton(entry and "Edit note and role..." or "Add with note and role...", function()
				SMA:Open(name, guid)
			end)
			sub:CreateButton("Swap " .. FaceText(FACE_AVOID) .. " lists", function() SMA:Share(name) end)
		end)
	end
end

----------------------------------------------------------------------------------------------------
-- Invite blocking
----------------------------------------------------------------------------------------------------

-- On-screen warning (raid warning style) for a player under review. Nothing is blocked.
-- At most once per player every few minutes, so a chatty whisperer doesn't flood the screen.
local REVIEW_WARN_COOLDOWN = 300
local reviewWarned = {} -- [key] = GetTime()

function SMA:WarnReview(name, guid)
	if not db or not Accessible(name) or not name then return end
	if not Accessible(guid) then guid = nil end
	local info = self:GetReview(name, guid)
	if not info then return end
	local key = Key(name)
	local now = GetTime()
	if reviewWarned[key] and now - reviewWarned[key] < REVIEW_WARN_COOLDOWN then return end
	if self:IsBNetFriend(name, guid) then return end
	reviewWarned[key] = now
	local who = Escape(info.name)
	local text = FaceText(FACE_REVIEW, 24) .. " " .. who .. ": previous poor behaviour reported. Proceed with care."
	if RaidWarningUtil and RaidWarningUtil.AddMessage then
		RaidWarningUtil.AddMessage(text, ChatTypeInfo and ChatTypeInfo["RAID_WARNING"], 8)
	elseif RaidNotice_AddMessage and RaidWarningFrame then
		RaidNotice_AddMessage(RaidWarningFrame, text, ChatTypeInfo and ChatTypeInfo["RAID_WARNING"], 8)
	end
	if PlaySound and SOUNDKIT and SOUNDKIT.RAID_WARNING then PlaySound(SOUNDKIT.RAID_WARNING) end
	Print(FaceText(FACE_REVIEW) .. " " .. who .. " is under review (" .. info.strikes .. " of " .. STRIKES
		.. " strikes" .. (info.claim and (", said to be in <" .. Escape(info.claim) .. ">, unconfirmed") or "")
		.. "). Previous poor behaviour reported, proceed with care.")
end

-- Wrap the outgoing invite functions so :( players are never invited (menus, /invite, friends list).
local function WrapInvite(funcName)
	local original = C_PartyInfo and C_PartyInfo[funcName]
	if not original then return end
	C_PartyInfo[funcName] = function(targetName, ...)
		if Accessible(targetName) and SMA:IsAvoided(targetName) and not SMA:IsBNetFriend(targetName) then
			Print(FaceText(FACE_AVOID) .. " " .. DisplayName(targetName) .. " is on your avoid list. Invite blocked.")
			return
		end
		if Accessible(targetName) then SMA:WarnReview(targetName) end
		return original(targetName, ...)
	end
end

local function HideInvitePopups()
	StaticPopup_Hide("PARTY_INVITE")
	if LFGInvitePopup and LFGInvitePopup:IsShown() then
		StaticPopupSpecial_Hide(LFGInvitePopup)
	end
end

local function OnPartyInviteRequest(name, ...)
	local inviterGUID = select(6, ...)
	if not Accessible(name) then name = nil end
	if not Accessible(inviterGUID) then inviterGUID = nil end

	local avoided = name and SMA:IsAvoided(name, inviterGUID)
	if not avoided and inviterGUID then
		local _, _, _, _, _, gName, gRealm = GetPlayerInfoByGUID(inviterGUID)
		if Accessible(gName) and gName then
			avoided = SMA:IsAvoided(gName)
			if not avoided and Accessible(gRealm) and gRealm and gRealm ~= "" then
				avoided = SMA:IsAvoided(gName .. REALM_SEP .. gRealm)
			end
		end
	end
	if not avoided then
		SMA:WarnReview(name, inviterGUID)
		return
	end
	if SMA:IsBNetFriend(name, inviterGUID) then return end

	DeclineGroup()
	HideInvitePopups()
	C_Timer.After(0, HideInvitePopups) -- in case Blizzard's handler runs after ours
	Print(FaceText(FACE_AVOID) .. " Declined a group invite from " .. (DisplayName(name) or "an avoided player") .. ".")
end

----------------------------------------------------------------------------------------------------
-- Ignore (addon-side, no limit; separate from the game's ignore list)
----------------------------------------------------------------------------------------------------

-- True if this player is on the :( list, ignoring is on, and they aren't a Battle.net friend.
local function ShouldIgnore(name, guid)
	if not (db and db.ignore) then return false end
	if not Accessible(name) or not name or name == "" then return false end
	if not Accessible(guid) then guid = nil end
	if not SMA:IsAvoided(name, guid) then return false end
	return not SMA:IsBNetFriend(name, guid)
end

-- Every chat frame runs the filter for every message, so remember the last answer.
local lastAuthor, lastGUID, lastTime, lastResult

local function ChatFilter(_, _, _, author, ...)
	local guid = select(10, ...) -- arg12 of CHAT_MSG_* (... starts at arg3)
	if not Accessible(author) or not author then return false end
	if not Accessible(guid) then guid = nil end
	local now = GetTime()
	if author ~= lastAuthor or guid ~= lastGUID or now ~= lastTime then
		lastAuthor, lastGUID, lastTime = author, guid, now
		lastResult = ShouldIgnore(author, guid)
	end
	return lastResult
end

local CHAT_EVENTS = {
	"CHAT_MSG_SAY", "CHAT_MSG_YELL", "CHAT_MSG_EMOTE", "CHAT_MSG_TEXT_EMOTE",
	"CHAT_MSG_WHISPER", "CHAT_MSG_CHANNEL",
	"CHAT_MSG_PARTY", "CHAT_MSG_PARTY_LEADER", "CHAT_MSG_RAID", "CHAT_MSG_RAID_LEADER",
	"CHAT_MSG_RAID_WARNING", "CHAT_MSG_INSTANCE_CHAT", "CHAT_MSG_INSTANCE_CHAT_LEADER",
	"CHAT_MSG_GUILD", "CHAT_MSG_OFFICER",
}

local function AddChatFilters()
	local add = (ChatFrameUtil and ChatFrameUtil.AddMessageEventFilter) or ChatFrame_AddMessageEventFilter
	if not add then return end
	for _, event in ipairs(CHAT_EVENTS) do add(event, ChatFilter) end
end

local function OnDuelRequested(name)
	if not ShouldIgnore(name) then return end
	CancelDuel()
	StaticPopup_Hide("DUEL_REQUESTED")
	C_Timer.After(0, function() StaticPopup_Hide("DUEL_REQUESTED") end)
	Print(FaceText(FACE_AVOID) .. " Declined a duel from " .. Escape(DisplayName(name)) .. ".")
end

local function OnTradeRequest(name)
	if not ShouldIgnore(name) then return end
	CancelTrade()
	StaticPopup_Hide("TRADE")
	C_Timer.After(0, function() StaticPopup_Hide("TRADE") end)
	Print(FaceText(FACE_AVOID) .. " Declined a trade from " .. Escape(DisplayName(name)) .. ".")
end

----------------------------------------------------------------------------------------------------
-- Guild rules: players in a guild whose name starts with one of db.avoidGuilds are added as :(
----------------------------------------------------------------------------------------------------
-- The game only tells us someone's guild for a unit (target, mouseover, group member, nameplate),
-- so players are picked up when you see them that way, not from chat names or invites alone.

-- You've seen a player in a guild that isn't avoided. If others claimed they were in one, the claim
-- is wrong (or out of date): drop it, and undo a guild lock that came from it.
function SMA:NoteNotInAvoidedGuild(key, display, guildName)
	if db.guildSeen[key] == guildName then return end
	local locked = db.locked[key]
	local hasClaim = locked ~= nil and locked.reason == "guild"
	if not hasClaim then
		for _, box in pairs(db.inbox) do
			local e = box.entries[key]
			if e and MatchGuildRule(e.guild) then hasClaim = true break end
		end
	end
	if not hasClaim then return end
	db.guildSeen[key] = guildName
	if locked and locked.reason == "guild" then db.locked[key] = nil end
	Print(FaceText(FACE_REVIEW) .. " " .. Escape(display) .. " is in <" .. Escape(guildName)
		.. ">, not an avoided guild, so the guild claim about them was ignored.")
	self:ApplyLocks() -- they may still have enough strikes
	if frame and frame:IsShown() then self:Refresh() end
end

function SMA:CheckUnitGuild(unit)
	if not db then return end
	local name = NameFromUnit(unit)
	if not name or IsMe(name) then return end
	local display = DisplayName(name)
	local key = display and Key(display)
	if not key then return end
	local guildName = GetGuildInfo(unit)
	if not Accessible(guildName) or not guildName or guildName == "" then return end
	local own = db.players[key]
	if own then
		own.guild = guildName -- remembered so it goes out with your shared :( entries
		return
	end
	if not MatchGuildRule(guildName) then
		self:NoteNotInAvoidedGuild(key, display, guildName)
		return
	end
	db.guildSeen[key] = nil
	if db.autoSkip[key] then return end
	local myGuild = GetGuildInfo("player")
	if Accessible(myGuild) and myGuild == guildName then return end -- never your own guild mates
	if not MatchGuildRule(guildName) then return end

	local guid = UnitGUID(unit)
	local role
	if UnitGroupRolesAssigned then
		local r = UnitGroupRolesAssigned(unit)
		if Accessible(r) and ROLE_BY_KEY[r] then role = r end
	end
	db.dismissed[key] = nil
	db.players[key] = {
		name = display,
		face = FACE_AVOID,
		role = role,
		note = "Auto: guild <" .. guildName .. ">",
		guid = Accessible(guid) and guid or nil,
		auto = guildName,
		guild = guildName,
		updated = time(),
	}
	Print(FaceText(FACE_AVOID) .. " Added " .. Escape(display) .. " (guild <" .. Escape(guildName) .. ">).")
	if frame and frame:IsShown() then self:Refresh() end
	self:OnOwnListChanged()
end

-- Players already warned about in the current group, so a roster update doesn't repeat it.
local groupWarned = {}

function SMA:CheckGroup()
	if not IsInGroup() then
		wipe(groupWarned)
		return
	end
	local units = {}
	if IsInRaid() then
		for i = 1, GetNumGroupMembers() do units[#units + 1] = "raid" .. i end
	else
		for i = 1, 4 do units[#units + 1] = "party" .. i end
	end
	for _, unit in ipairs(units) do
		self:CheckUnitGuild(unit)
		local name = NameFromUnit(unit)
		local key = name and Key(name)
		if key and not groupWarned[key] then
			groupWarned[key] = true
			local guid = UnitGUID(unit)
			self:WarnReview(name, guid)
		end
	end
end

-- /sma avoidguild [add|remove] <prefix>
function SMA:GuildRuleCommand(args)
	local action, prefix = args:match("^(%S+)%s*(.-)%s*$")
	if action ~= "add" and action ~= "remove" then
		action, prefix = (args ~= "" and "add" or nil), strtrim(args)
	end
	local function IsBuiltin(p)
		for _, b in ipairs(BUILTIN_GUILDS) do
			if strlower(b) == strlower(p) then return b end
		end
	end
	if action == "remove" and prefix ~= "" and IsBuiltin(prefix) then
		Print("\"" .. IsBuiltin(prefix) .. "\" is built in for everyone and can't be removed.")
		return
	end
	if action == "add" and prefix ~= "" then
		if IsBuiltin(prefix) then Print("\"" .. IsBuiltin(prefix) .. "\" is already built in.") return end
		for _, p in ipairs(db.avoidGuilds) do
			if strlower(p) == strlower(prefix) then Print("Already avoiding guilds starting with \"" .. p .. "\".") return end
		end
		table.insert(db.avoidGuilds, prefix)
		Print("Guilds starting with \"" .. prefix .. "\" are now added as " .. FaceText(FACE_AVOID) .. " when you see their members.")
		if UnitExists("target") then self:CheckUnitGuild("target") end
		self:CheckGroup()
	elseif action == "remove" and prefix ~= "" then
		local removed
		for i, p in ipairs(db.avoidGuilds) do
			if strlower(p) == strlower(prefix) then removed = table.remove(db.avoidGuilds, i) break end
		end
		if not removed then Print("No guild rule for \"" .. prefix .. "\".") return end
		-- drop the untouched :( entries that rule added
		local n = 0
		for key, e in pairs(db.players) do
			if e.auto and e.face == FACE_AVOID and not MatchGuildRule(e.auto)
				and strlower(e.auto):sub(1, #removed) == strlower(removed) then
				db.players[key] = nil
				n = n + 1
			end
		end
		Print("Removed the guild rule \"" .. removed .. "\" and " .. n .. " players it added.")
		if frame and frame:IsShown() then self:Refresh() end
		if n > 0 then self:OnOwnListChanged() end
	else
		Print("Built in for everyone: guilds starting with " .. table.concat(BUILTIN_GUILDS, ", ") .. ".")
		if #db.avoidGuilds == 0 then
			Print("Your own rules: none. Add one with /sma avoidguild <start of guild name>.")
		else
			Print("Your own rules: " .. table.concat(db.avoidGuilds, ", ") .. ".")
		end
	end
end

function SMA:SetIgnore(on)
	db.ignore = on and true or false
	lastAuthor = nil
	if frame then frame.ignoreCheck:SetChecked(db.ignore) end
	Print("Ignoring " .. FaceText(FACE_AVOID) .. " players " .. (db.ignore and "on" or "off") .. ".")
end

----------------------------------------------------------------------------------------------------
-- Sharing (always mutual: both sides agree, both sides send)
----------------------------------------------------------------------------------------------------
-- Direct swap (WHISPER):
--   OFFER <count>          A -> B. B gets a popup; nothing has been sent yet.
--   ACCEPT / DECLINE       B -> A. On accept, both sides send their lists.
-- Guild (control on GUILD, data on WHISPER). Only between players who ticked "Share with guild":
--   HELLO                  "I've opted in" (on login / when ticked)
--   HI <name>              reply from an opted-in player to <name>'s HELLO; <name> then sends theirs
--   BYE                    "I've opted out": drop my list
-- A message on the GUILD channel proves the sender is in your guild, so data is only accepted
-- from guild senders seen on that channel this session.
-- List transfer (WHISPER): BEGIN <direct|guild>, E <name> <role> per entry, END. Notes stay private.
-- A transfer replaces that sender's previous list, so their deletions carry over.
-- Only your own :( entries are sent; entries you received are never passed on.

local COMM_PREFIX = "SnogMarryAvoid"
local MAX_MSG = 255
local OFFER_TTL = 120
local MAX_ENTRIES = 1000

local outgoingOffers = {} -- [receiverKey] = expiry time
local directAccepted = {} -- [senderKey] = expiry time: we agreed to a swap with them
local guildPeers = {}     -- [senderKey] = true: opted-in guild mates seen on the GUILD channel
local transfers = {}      -- [senderKey] = { via, entries, count, expires }
local sendQueue = {}
local sendTicker, syncTimer

local THROTTLED = Enum.SendAddonMessageResult and Enum.SendAddonMessageResult.AddonMessageThrottle
local SUCCESS = Enum.SendAddonMessageResult and Enum.SendAddonMessageResult.Success

-- Cut a string to maxBytes without splitting a UTF-8 character.
local function TruncateUTF8(s, maxBytes)
	if #s <= maxBytes then return s end
	s = s:sub(1, maxBytes)
	local i = #s
	while i > 0 and s:byte(i) >= 0x80 and s:byte(i) < 0xC0 do i = i - 1 end
	if i > 0 and s:byte(i) >= 0xC0 then
		local lead = s:byte(i)
		local len = lead >= 0xF0 and 4 or lead >= 0xE0 and 3 or 2
		if #s - i + 1 < len then s = s:sub(1, i - 1) end
	end
	return s
end

local function ProcessSendQueue()
	local item = sendQueue[1]
	if not item then
		sendTicker:Cancel()
		sendTicker = nil
		return
	end
	local result = C_ChatInfo.SendAddonMessage(COMM_PREFIX, item.msg, item.chatType, item.target)
	if THROTTLED and result == THROTTLED then return end -- try again next tick
	table.remove(sendQueue, 1)
	if SUCCESS and result ~= SUCCESS and item.target then
		-- Drop the rest of this transfer; it can't arrive complete.
		for i = #sendQueue, 1, -1 do
			if sendQueue[i].target == item.target then table.remove(sendQueue, i) end
		end
		if not item.quiet then
			Print("Couldn't send to " .. item.target .. " (error " .. tostring(result) .. "). Try again out of combat/instances.")
		end
	end
end

local function Enqueue(msg, target, quiet)
	sendQueue[#sendQueue + 1] = {
		msg = TruncateUTF8(msg, MAX_MSG),
		chatType = target and "WHISPER" or "GUILD",
		target = target,
		quiet = quiet,
	}
	if not sendTicker then
		sendTicker = C_Timer.NewTicker(0.2, ProcessSendQueue)
	end
end

local function OwnAvoidEntries()
	local list = {}
	for _, entry in pairs(db.players) do
		if entry.face == FACE_AVOID then list[#list + 1] = entry end
	end
	return list
end

local function SendList(target, via)
	local list = OwnAvoidEntries()
	local quiet = via == "guild"
	Enqueue("BEGIN\t" .. via, target, quiet)
	local code = ReporterCode()
	if code then Enqueue("ID\t" .. code, target, quiet) end -- a separate message, so older versions ignore it
	for _, entry in ipairs(list) do
		-- Notes are private and never sent: they're personal opinions that could read as unfair to others.
		-- The guild (prefixed "G:", so older versions that read a note field here can't confuse it)
		-- lets the receiver tell an always-avoided guild member from a one-off report.
		local guild = entry.guild or entry.auto
		Enqueue("E\t" .. entry.name .. "\t" .. (entry.role or "") .. (guild and ("\tG:" .. guild) or ""), target, quiet)
	end
	Enqueue("END", target, quiet)
	return #list
end

-- Direct swap ------------------------------------------------------------------------------------

function SMA:Share(target)
	target = type(target) == "string" and strtrim(target) or ""
	if target == "" then
		StaticPopup_Show("SNOGMARRYAVOID_SHARE")
		return
	end
	if IsMe(target) then
		Print("You can't swap with yourself.")
		return
	end
	outgoingOffers[Key(target)] = GetTime() + OFFER_TTL
	Enqueue("OFFER\t" .. #OwnAvoidEntries(), target)
	Print("Offered to swap " .. FaceText(FACE_AVOID) .. " lists with " .. target .. ". Waiting for them to accept.")
end

-- Guild ------------------------------------------------------------------------------------------

local function DropGuildInbox(senderKey)
	for key, box in pairs(db.inbox) do
		if box.via == "guild" and (not senderKey or key == senderKey) then
			db.inbox[key] = nil
		end
	end
end

function SMA:GuildHello()
	if db.guildShare and IsInGuild() then
		Enqueue("HELLO", nil, true)
	end
end

function SMA:SetGuildShare(on)
	on = not not on
	if on == not not db.guildShare then return end
	db.guildShare = on
	if on then
		if not IsInGuild() then
			Print("Guild sharing is on, but you're not in a guild.")
		else
			Print("Guild sharing on. Swapping " .. FaceText(FACE_AVOID) .. " lists with guild mates who have it on too.")
		end
		self:GuildHello()
	else
		if IsInGuild() then Enqueue("BYE", nil, true) end
		wipe(guildPeers)
		DropGuildInbox()
		Print("Guild sharing off. Your list was withdrawn and guild lists removed.")
	end
	if frame then frame.guildCheck:SetChecked(on) end
	self:Refresh()
end

-- Send the updated list to opted-in guild mates a few seconds after the last change.
function SMA:OnOwnListChanged()
	if not db.guildShare then return end
	if syncTimer then syncTimer:Cancel() end
	syncTimer = C_Timer.NewTimer(5, function()
		syncTimer = nil
		if not db.guildShare then return end
		for _, peer in pairs(guildPeers) do
			SendList(peer, "guild")
		end
	end)
end

-- Receiving --------------------------------------------------------------------------------------

local function OnAddonMessage(prefix, text, channel, sender)
	if prefix ~= COMM_PREFIX then return end
	if not (Accessible(text) and Accessible(sender)) or IsMe(sender) then return end
	local senderKey = Key(sender)
	if not senderKey then return end
	local cmd, rest = strsplit("\t", text, 2)
	local now = GetTime()

	if channel == "GUILD" then
		if not db.guildShare then return end
		if cmd == "HELLO" then
			guildPeers[senderKey] = sender
			Enqueue("HI\t" .. sender, nil, true)
			SendList(sender, "guild")
		elseif cmd == "HI" then
			guildPeers[senderKey] = sender
			if rest and IsMe(rest) then SendList(sender, "guild") end
		elseif cmd == "BYE" then
			guildPeers[senderKey] = nil
			DropGuildInbox(senderKey)
			SMA:Refresh()
		end
		return
	end
	if channel ~= "WHISPER" then return end

	if cmd == "OFFER" then
		StaticPopup_Show("SNOGMARRYAVOID_OFFER", Escape(DisplayName(sender)), tonumber(rest) or 0, sender)
	elseif cmd == "ACCEPT" then
		local expires = outgoingOffers[senderKey]
		if not expires or expires < now then return end
		outgoingOffers[senderKey] = nil
		directAccepted[senderKey] = now + OFFER_TTL
		Print(sender .. " accepted. Sending " .. SendList(sender, "direct") .. " entries.")
	elseif cmd == "DECLINE" then
		if outgoingOffers[senderKey] then
			outgoingOffers[senderKey] = nil
			Print(sender .. " declined the swap.")
		end
	elseif cmd == "BEGIN" then
		local allowed
		if rest == "direct" then
			allowed = (directAccepted[senderKey] or 0) >= now
		elseif rest == "guild" then
			allowed = db.guildShare and guildPeers[senderKey] ~= nil
		end
		if allowed then
			transfers[senderKey] = { via = rest, entries = {}, count = 0, expires = now + OFFER_TTL }
		end
	elseif cmd == "ID" then
		local t = transfers[senderKey]
		local code = tonumber(rest)
		if t and t.expires >= now and code and code >= 0 and code < REPORTER_CODES and code == math.floor(code) then
			t.code = code
		end
	elseif cmd == "E" then
		local t = transfers[senderKey]
		if not t or t.expires < now or not rest or t.count >= MAX_ENTRIES then return end
		local name, role, extra = strsplit("\t", rest, 3) -- extra: "G:<guild>", or a note from v1.0 (ignored)
		local key = Key(name)
		if not key or IsMe(name) then return end
		local guild = extra and extra:match("^G:(.+)$")
		if not t.entries[key] then t.count = t.count + 1 end
		t.entries[key] = {
			name = DisplayName(name),
			role = ROLE_BY_KEY[role or ""] and role or nil,
			guild = guild and guild:sub(1, 48) or nil,
		}
		t.expires = now + OFFER_TTL
	elseif cmd == "END" then
		local t = transfers[senderKey]
		if not t or t.expires < now then return end
		transfers[senderKey] = nil
		if t.via == "direct" then directAccepted[senderKey] = nil end
		local previous = db.inbox[senderKey]
		db.inbox[senderKey] = { from = DisplayName(sender), via = t.via, code = t.code, updated = time(), entries = t.entries }
		local who = Escape(DisplayName(sender))
		if t.via == "direct" then
			Print("Received " .. t.count .. " " .. FaceText(FACE_AVOID) .. " entries from " .. who .. ".")
		elseif not previous then
			Print("Guild mate " .. who .. " shared " .. t.count .. " " .. FaceText(FACE_AVOID) .. " entries.")
		end
		SMA:ApplyLocks()
		SMA:Refresh()
	end
end

StaticPopupDialogs["SNOGMARRYAVOID_OFFER"] = {
	text = "SnogMarryAvoid: %s wants to swap avoid lists (they have %d).\n\nAccepting sends them your :( list too.\nOnly names and roles are shared; notes stay private.",
	button1 = ACCEPT or "Accept",
	button2 = DECLINE or "Decline",
	OnAccept = function(_, sender)
		local senderKey = Key(sender)
		directAccepted[senderKey] = GetTime() + OFFER_TTL
		Enqueue("ACCEPT", sender)
		SendList(sender, "direct")
	end,
	OnCancel = function(_, sender, reason)
		if reason == "clicked" then Enqueue("DECLINE", sender) end
	end,
	timeout = 60,
	whileDead = 1,
	hideOnEscape = 1,
}

StaticPopupDialogs["SNOGMARRYAVOID_SHARE"] = {
	text = "Swap " .. FaceText(FACE_AVOID) .. " lists with which player?",
	button1 = "Offer",
	button2 = CANCEL or "Cancel",
	hasEditBox = 1,
	OnAccept = function(dialog)
		SMA:Share(dialog:GetEditBox():GetText())
	end,
	EditBoxOnEnterPressed = function(editBox)
		local dialog = editBox:GetParent()
		SMA:Share(dialog:GetEditBox():GetText())
		dialog:Hide()
	end,
	EditBoxOnEscapePressed = function(editBox) editBox:GetParent():Hide() end,
	timeout = 0,
	whileDead = 1,
	hideOnEscape = 1,
}

----------------------------------------------------------------------------------------------------
-- Minimap button & addon compartment
----------------------------------------------------------------------------------------------------

local ICON = MEDIA .. "happy"
local minimapButton

local function PositionMinimapButton()
	local angle = math.rad(db.minimap.angle or 200)
	local radius = Minimap:GetWidth() / 2 + 10
	minimapButton:ClearAllPoints()
	minimapButton:SetPoint("CENTER", Minimap, "CENTER", math.cos(angle) * radius, math.sin(angle) * radius)
end

local function MinimapButtonDragUpdate()
	local mx, my = Minimap:GetCenter()
	local scale = Minimap:GetEffectiveScale()
	local cx, cy = GetCursorPosition()
	db.minimap.angle = math.deg(math.atan2(cy / scale - my, cx / scale - mx))
	PositionMinimapButton()
end

local function CreateMinimapButton()
	local b = CreateFrame("Button", "SnogMarryAvoidMinimapButton", Minimap)
	minimapButton = b
	b:SetSize(31, 31)
	b:SetFrameStrata("MEDIUM")
	b:SetFrameLevel(8)
	b:RegisterForClicks("LeftButtonUp", "RightButtonUp")
	b:RegisterForDrag("LeftButton")
	b:SetHighlightTexture("Interface\\Minimap\\UI-Minimap-ZoomButton-Highlight")

	local bg = b:CreateTexture(nil, "BACKGROUND")
	bg:SetTexture("Interface\\Minimap\\UI-Minimap-Background")
	bg:SetSize(20, 20)
	bg:SetPoint("TOPLEFT", 7, -5)

	local icon = b:CreateTexture(nil, "ARTWORK")
	icon:SetTexture(ICON)
	icon:SetSize(19, 19)
	icon:SetPoint("TOPLEFT", 6, -5)

	local border = b:CreateTexture(nil, "OVERLAY")
	border:SetTexture("Interface\\Minimap\\MiniMap-TrackingBorder")
	border:SetSize(53, 53)
	border:SetPoint("TOPLEFT")

	b:SetScript("OnClick", function() SMA:Toggle() end)
	b:SetScript("OnDragStart", function(self) self:SetScript("OnUpdate", MinimapButtonDragUpdate) end)
	b:SetScript("OnDragStop", function(self) self:SetScript("OnUpdate", nil) end)
	b:SetScript("OnEnter", function(self)
		GameTooltip:SetOwner(self, "ANCHOR_LEFT")
		GameTooltip:SetText("SnogMarryAvoid")
		GameTooltip:AddLine("Click to open. Drag to move.", 1, 1, 1)
		GameTooltip:AddLine("/sma minimap to hide this button.", 0.7, 0.7, 0.7)
		GameTooltip:Show()
	end)
	b:SetScript("OnLeave", GameTooltip_Hide)

	PositionMinimapButton()
	b:SetShown(not db.minimap.hide)
end

function SnogMarryAvoid_OnAddonCompartmentClick()
	SMA:Toggle()
end

