-- Events & slash command
----------------------------------------------------------------------------------------------------

local events = CreateFrame("Frame")
events:RegisterEvent("ADDON_LOADED")
events:RegisterEvent("PARTY_INVITE_REQUEST")
events:SetScript("OnEvent", function(self, event, ...)
	if event == "ADDON_LOADED" then
		if ... ~= ADDON_NAME then return end
		SnogMarryAvoidDB = SnogMarryAvoidDB or {}
		db = SnogMarryAvoidDB
		db.players = db.players or {}
		db.minimap = db.minimap or {}
		db.inbox = db.inbox or {}
		db.dismissed = db.dismissed or {}
		if db.ignore == nil then db.ignore = true end
		db.avoidGuilds = db.avoidGuilds or {}
		db.autoSkip = db.autoSkip or {}
		db.locked = db.locked or {}
		db.guildSeen = db.guildSeen or {}
		if (db.schema or 1) < 2 then
			-- 1.5 locked a player on a single sender's guild claim; re-check those under the new rules
			for key, l in pairs(db.locked) do
				if l.reason == "guild" then db.locked[key] = nil end
			end
			db.schema = 2
		end
		for i = #db.avoidGuilds, 1, -1 do -- built-in rules don't need a personal copy
			for _, b in ipairs(BUILTIN_GUILDS) do
				if strlower(db.avoidGuilds[i]) == strlower(b) then table.remove(db.avoidGuilds, i) break end
			end
		end
		if db.shared then -- 1.0 dev builds kept one flat table of shared entries
			for key, s in pairs(db.shared) do
				local senderKey = Key(s.from) or "?"
				local box = db.inbox[senderKey] or { from = s.from, via = "direct", updated = s.received, entries = {} }
				box.entries[key] = { name = s.name, role = s.role }
				db.inbox[senderKey] = box
			end
			db.shared = nil
		end
		for _, box in pairs(db.inbox) do -- notes are no longer shared; drop any received earlier
			for _, e in pairs(box.entries) do e.note = nil end
		end
		SMA:ApplyLocks(true)
		C_ChatInfo.RegisterAddonMessagePrefix(COMM_PREFIX)
		AddMenuEntries()
		CreateMinimapButton()
		WrapInvite("InviteUnit")
		WrapInvite("ConfirmInviteUnit")
		AddChatFilters()
		self:UnregisterEvent("ADDON_LOADED")
	elseif event == "PARTY_INVITE_REQUEST" then
		if db then OnPartyInviteRequest(...) end
	elseif event == "PLAYER_TARGET_CHANGED" then
		SMA:CheckUnitGuild("target")
	elseif event == "UPDATE_MOUSEOVER_UNIT" then
		SMA:CheckUnitGuild("mouseover")
	elseif event == "NAME_PLATE_UNIT_ADDED" then
		SMA:CheckUnitGuild((...))
	elseif event == "GROUP_ROSTER_UPDATE" then
		if db then SMA:CheckGroup() end
	elseif event == "CHAT_MSG_WHISPER" then
		if db then
			local _, sender = ...
			SMA:WarnReview(sender, (select(12, ...)))
		end
	elseif event == "DUEL_REQUESTED" then
		if db then OnDuelRequested(...) end
	elseif event == "TRADE_REQUEST" then
		if db then OnTradeRequest(...) end
	elseif event == "CHAT_MSG_ADDON" then
		if db then OnAddonMessage(...) end
	elseif event == "PLAYER_ENTERING_WORLD" then
		local isInitialLogin, isReload = ...
		if db and (isInitialLogin or isReload) then
			C_Timer.After(10, function() SMA:GuildHello() end) -- guild roster/channel needs a moment
		end
	end
end)
events:RegisterEvent("CHAT_MSG_ADDON")
events:RegisterEvent("PLAYER_ENTERING_WORLD")
events:RegisterEvent("DUEL_REQUESTED")
events:RegisterEvent("TRADE_REQUEST")
events:RegisterEvent("PLAYER_TARGET_CHANGED")
events:RegisterEvent("UPDATE_MOUSEOVER_UNIT")
events:RegisterEvent("NAME_PLATE_UNIT_ADDED")
events:RegisterEvent("GROUP_ROSTER_UPDATE")
events:RegisterEvent("CHAT_MSG_WHISPER")

SLASH_SNOGMARRYAVOID1 = "/sma"
SLASH_SNOGMARRYAVOID2 = "/snogmarryavoid"
SlashCmdList.SNOGMARRYAVOID = function(msg)
	msg = strtrim(msg or "")
	if msg == "" then
		SMA:Toggle()
	elseif msg == "minimap" then
		db.minimap.hide = not db.minimap.hide
		minimapButton:SetShown(not db.minimap.hide)
		Print("Minimap button " .. (db.minimap.hide and "hidden" or "shown") .. ".")
	elseif msg == "guild" then
		SMA:SetGuildShare(not db.guildShare)
	elseif msg == "ignore" then
		SMA:SetIgnore(not db.ignore)
	elseif msg == "avoidguild" or msg:find("^avoidguild ") then
		SMA:GuildRuleCommand(strtrim(msg:sub(11)))
	elseif msg == "share" or msg:find("^share ") then
		local target = strtrim(msg:sub(6))
		if target == "" then target = NameFromUnit("target") or "" end
		SMA:Share(target)
	elseif msg == "target" then
		local name = NameFromUnit("target")
		if name and not IsMe(name) then
			local guid = UnitGUID("target")
			SMA:Open(name, Accessible(guid) and guid or nil)
		else
			Print("Your target isn't another player.")
		end
	else
		SMA:Open(msg)
	end
end
